DROP TABLE IF EXISTS fund_beneficiaries;


CREATE TABLE fund_beneficiaries (
  idBeneficiary INTEGER NOT NULL,
  FundID INTEGER NOT NULL,
  ResidentID INTEGER NOT NULL,
  AllocatedAmount REAL NOT NULL DEFAULT 0.00,
  IsReleased INTEGER NOT NULL DEFAULT 0,
  DateReleased TEXT DEFAULT NULL,
  ReleasedBy TEXT DEFAULT NULL,
  AddedBy TEXT DEFAULT NULL,
  DateAdded TEXT DEFAULT NULL,
  PRIMARY KEY (idBeneficiary),
  CONSTRAINT fund_beneficiaries_ibfk_1 FOREIGN KEY (ResidentID) REFERENCES resident (idResident)
);








