DROP TABLE IF EXISTS incidentreports;


CREATE TABLE incidentreports (
  idIncidentReports INTEGER NOT NULL,
  ReportNumber TEXT NOT NULL,
  DateReported TEXT DEFAULT current_timestamp(),
  ReportedByID INTEGER DEFAULT NULL,
  IncidentType TEXT DEFAULT NULL,
  Description TEXT NOT NULL,
  Location TEXT DEFAULT NULL,
  Severity TEXT DEFAULT 'Low',
  Status TEXT DEFAULT 'Open',
  AssignedTo TEXT DEFAULT NULL,
  ResolvedDate TEXT DEFAULT NULL,
  Remarks TEXT DEFAULT NULL,
  PRIMARY KEY (idIncidentReports),
  CONSTRAINT fk_IncidentReports_ReportedByID FOREIGN KEY (ReportedByID) REFERENCES resident (idResident)
);








