DROP TABLE IF EXISTS resident;


CREATE TABLE resident (
  idResident INTEGER NOT NULL,
  FirstName TEXT NOT NULL,
  LastName TEXT NOT NULL,
  MiddleName TEXT NOT NULL,
  DateOfBirth TEXT DEFAULT NULL,
  Gender TEXT DEFAULT NULL,
  CivilStatus TEXT DEFAULT 'Single',
  Occupation TEXT DEFAULT NULL,
  ContactNumber TEXT DEFAULT NULL,
  Email TEXT DEFAULT NULL,
  Address TEXT DEFAULT NULL,
  Photo BLOB DEFAULT NULL,
  IsActive INTEGER DEFAULT 1,
  IsRegisteredVoter INTEGER NOT NULL DEFAULT 0,
  Is4PsBeneficiary INTEGER NOT NULL DEFAULT 0,
  HouseholdNumber TEXT DEFAULT NULL,
  EmergencyContactName TEXT DEFAULT NULL,
  EmergencyContactRelation TEXT DEFAULT NULL,
  EmergencyContactPhone TEXT DEFAULT NULL,
  DateRegistered TEXT DEFAULT NULL,
  CreatedAt TEXT DEFAULT current_timestamp(),
  PlaceOfBirth TEXT DEFAULT NULL,
  Citizenship TEXT NOT NULL DEFAULT 'Filipino',
  Height TEXT DEFAULT NULL,
  Weight TEXT DEFAULT NULL,
  TIN TEXT DEFAULT NULL,
  ICRNumber TEXT DEFAULT NULL,
  PRIMARY KEY (idResident)
