DROP TABLE IF EXISTS users;


CREATE TABLE users (
  idUsers INTEGER NOT NULL,
  Username TEXT NOT NULL,
  Password TEXT NOT NULL,
  Role TEXT NOT NULL DEFAULT 'User',
  IsActive INTEGER DEFAULT 1,
  CreatedAt TEXT DEFAULT current_timestamp(),
  PRIMARY KEY (idUsers)
);








